const input = Array.isArray($json) ? $json : [$json];
let skippedNoConsent = 0;
const rows = [];
for (const member of input) {
  if (!member.optInSource) {
    skippedNoConsent += 1;
    continue;
  }
  const expired = member.planStatus === 'expired';
  const systemAge = Number(`${member.systemAge ?? '0'}`.replace(/\D/g, ''));
  const segment = expired ? 'renewal-campaign' : systemAge >= 8 ? 'replacement-watchlist' : 'next-season-tune-up';
  rows.push({ json: { ...member, segment, nextAction: expired ? 'Send renewal offer.' : 'Schedule seasonal reminder.' } });
}
rows.push({ json: { summary: true, processed: rows.length, skippedNoConsent, note: 'Records without optInSource are excluded from all sends. FCC one-to-one consent: no purchased or shared lists.' } });
return rows;
